INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5001, 'Deuteronomy 20:12', 'Deuteronomy', 20, 12, '&nbsp;خو کۀ د هغه ښار خلق تسليم نۀ شى او جنګ خوښ کړى، نو د خپل لښکر سره يې محاصره کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5002, 'Deuteronomy 20:13', 'Deuteronomy', 20, 13, '&nbsp;نو کله چې مالِک خُدائ ستاسو خُدائ پاک وکړى چې تاسو هغه ښار قبضه کړئ، نو په دې کښې ټول سړى ووژنئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5003, 'Deuteronomy 20:14', 'Deuteronomy', 20, 14, '&nbsp;خو هغه ښځې، ماشومان، څاروى او چې په ښار کښې نور هر څۀ وى هغه د ځان دپاره اخستے شئ. تاسو د خپلو دشمنانو هر څيز استعمالولے شئ. مالِک خُدائ دا تاسو له درکړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5004, 'Deuteronomy 20:15', 'Deuteronomy', 20, 15, '&nbsp;تاسو به د هغه ښارونو سره داسې کار وکړئ کوم چې د هغه مُلک نه لرې دى چرته به چې تاسو اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5005, 'Deuteronomy 20:16', 'Deuteronomy', 20, 16, '&nbsp;خو کله چې تاسو د هغه مُلک ښارونه قبضه کړئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى، نو هر يو کس ووژنئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5006, 'Deuteronomy 20:17', 'Deuteronomy', 20, 17, '&nbsp;دا ټول خلق تباه کړئ يعنې حِتيان، اموريان، کنعانيان، فرزيان، حِويان او يبوسيان، لکه څنګه چې مالِک خُدائ د دې حُکم درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5007, 'Deuteronomy 20:18', 'Deuteronomy', 20, 18, '&nbsp;دا خلق ووژنئ، نو هغوئ به تاسو د مالِک خُدائ خِلاف ګناهګار نۀ کړى چې تاسو ته هغه ټول بد عملونه وښائى چې هغوئ يې د خپلو معبودانو په عبادت کښې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5008, 'Deuteronomy 20:19', 'Deuteronomy', 20, 19, '&nbsp;کله چې تاسو د يو ښار د قبضه کولو کوشش کوئ، نو د هغه ځائ مېوه دارې ونې مۀ پرې کوئ، اګر چې محاصره د ډېر وخت پورې اوږده هم شى. مېوه يې خورئ، خو ونې مۀ تباه کوئ، ځکه چې ونې ستاسو دشمنانې نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5009, 'Deuteronomy 20:20', 'Deuteronomy', 20, 20, '&nbsp;تاسو هغه هره ونه راماتولے شئ کومه چې مېوه نۀ نيسى او د ښار د قبضه کېدو پورې تاسو هغه د محاصرې د دېوالونو دپاره استعمالولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5010, 'Deuteronomy 21:1', 'Deuteronomy', 21, 1, '&nbsp;کۀ په يو پټى کښې يو قتل شوے کس وموندے شى په هغه مُلک کښې چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى او تاسو ته پته نۀ وى چې چا وژلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5011, 'Deuteronomy 21:2', 'Deuteronomy', 21, 2, '&nbsp;نو ستاسو مشران او قاضيان به لاړ شى او چې چرته هغه مړے موندلے شوے وى نو د هغه ځائ نه به د ټولو نزدې ښارونو فاصله معلومه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5012, 'Deuteronomy 21:3', 'Deuteronomy', 21, 3, '&nbsp;نو چې چرته مړے موندلے شوے وى د هغه نزدې ښار مشران به يوه سخۍ خوښه کړى چې هيڅ کار ترې نه نۀ وى اخستے شوے او نۀ يې جغ راښکلے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5013, 'Deuteronomy 21:4', 'Deuteronomy', 21, 4, '&nbsp;هغوئ به دا يوې بهېدونکې ولې ته کوزه کړى چې د هغه ځائ زمکه هيڅکله نه يوې شوې وى او نه کَرلے شوې وى او هغوئ به هلته د دې سخۍ څټ مات کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5014, 'Deuteronomy 21:5', 'Deuteronomy', 21, 5, '&nbsp;د ليوى قبيلې اِمامان به هم هلته لاړ شى، ځکه چې هغوئ به هره هغه لانجه فېصله کوى چې د ظلم او زياتى سره يې تعلق وى. مالِک خُدائ ستاسو خُدائ پاک هغوئ د خپل خِدمت دپاره خوښ کړى دى او چې د هغۀ په نوم برکتونه وغواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5015, 'Deuteronomy 21:6', 'Deuteronomy', 21, 6, '&nbsp;بيا چې چرته هغه قتل شوے کس موندلے شوے وى هغې ته د نزدې ښار ټول مشران به په هغه سخۍ باندې خپل لاسونه ووينځى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5016, 'Deuteronomy 21:7', 'Deuteronomy', 21, 7, '&nbsp;او هغوئ دې ووائى چې، مونږ دا کس نۀ دے وژلے او مونږ ته پته نشته چې دا قتل چا کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5017, 'Deuteronomy 21:8', 'Deuteronomy', 21, 8, '&nbsp;اے مالِکه خُدايه، خپل خلق اِسرائيليان معاف کړه څوک دې چې تا د مِصر نه آزاد کړل. مونږ معاف کړه او د يو بې‌ګناه کس د قتل ذمه وارى زمونږ په غاړه مۀ اچوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5018, 'Deuteronomy 21:9', 'Deuteronomy', 21, 9, '&nbsp;چې هغه څۀ وکړئ چې مالِک خُدائ يې غواړى، نو د قتل ذمه وارى به ستاسو په غاړه نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5019, 'Deuteronomy 21:10', 'Deuteronomy', 21, 10, '&nbsp;کله چې تاسو د خپلو دشمنانو خِلاف جنګ له لاړ شئ او مالِک خُدائ ستاسو خُدائ پاک تاسو په هغوئ زورَور کړى او څۀ کسان ترې نه قېديان کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5020, 'Deuteronomy 21:11', 'Deuteronomy', 21, 11, '&nbsp;کېدے شى چې تاسو په هغوئ کښې يوه ښائسته ښځه وګورئ چې ستاسو خوښه شى او ورسره وادۀ کول وغواړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5021, 'Deuteronomy 21:12', 'Deuteronomy', 21, 12, '&nbsp;هغه خپل کور ته بوځئ، هلته به خپل سر کل کړى، نوکونه به پرې کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5022, 'Deuteronomy 21:13', 'Deuteronomy', 21, 13, '&nbsp;او خپلې جامې به بدلې کړى. هغه به ستاسو په کور کښې ايساره شى او خپل مور پلار پسې به يوه مياشت وژاړى، د هغې نه پس، هغه وادۀ کولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5023, 'Deuteronomy 21:14', 'Deuteronomy', 21, 14, '&nbsp;وروستو، کۀ تاسو د هغې سره خوشحاله نۀ يئ، نو تاسو يې پرېښودے شئ او چې چرته وغواړى نو هلته دې لاړه شى. ځکه چې تاسو د هغې بې‌عزتى کړې ده، نو تاسو د هغې سره د يوې وينځې په شان سلوک نۀ شئ کولے او نۀ يې خرڅولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5024, 'Deuteronomy 21:15', 'Deuteronomy', 21, 15, '&nbsp;کۀ د يو سړى دوه ښځې وى او هغه د يوې سره مينه کوى او د بلې سره نۀ کوى او د دواړو نه يې زامن پېدا شى، خو وړومبے زوئ يې د هغې ښځې نه وى چې د کومې سره مينه نۀ کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5025, 'Deuteronomy 21:16', 'Deuteronomy', 21, 16, '&nbsp;کله چې هغه سړے خپل جائيداد تقسيموى نو هغه دې د خپلې خوښې ښځې زوئ له د مشرى زوئ حق نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5026, 'Deuteronomy 21:17', 'Deuteronomy', 21, 17, '&nbsp;چې د کومې ښځې سره مينه نۀ کوى خو د هغې زوئ مشر دے نو هغۀ له به يو په دوه برخه ورکوى. مشر زوئ د خپل پلار د طاقت وړومبۍ نښه وى. هغه د مشرۍ حق لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5027, 'Deuteronomy 21:18', 'Deuteronomy', 21, 18, '&nbsp;کۀ د چا زوئ ضدى يا سرکشه وى، يو زوئ چې د خپل مور پلار فرمانبردارى نۀ کوى، تر دې پورې چې هغوئ سزا هم ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5028, 'Deuteronomy 21:19', 'Deuteronomy', 21, 19, '&nbsp;د هغۀ مور پلار دې هغه د ښار مشرانو له راولى چرته چې هغه اوسيږى او په هغۀ دې فېصله وکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5029, 'Deuteronomy 21:20', 'Deuteronomy', 21, 20, '&nbsp;هغوئ دې مشرانو ته داسې ووائى، ”زمونږ زوئ ضدى او سرکشه دے او زمونږ خبره نۀ منى، هغه فضول خرچه او شرابى دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5030, 'Deuteronomy 21:21', 'Deuteronomy', 21, 21, '&nbsp;نو د ښار سړى دې هغه سنګسار کړى چې مړ شى. نو تاسو به د دې بدکارۍ نه خلاص شئ. په بنى اِسرائيلو کښې به ټول خلق د دې نه خبر شى او وبه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5031, 'Deuteronomy 21:22', 'Deuteronomy', 21, 22, '&nbsp;کۀ د يو جرم په وجه څوک وژلے شوے وى او د هغۀ لاش په يوه ونه کښې ځوړند وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5032, 'Deuteronomy 21:23', 'Deuteronomy', 21, 23, '&nbsp;نو هغه دې د شپې هلته نۀ شى پرېښودلے. هغه دې خامخا هم په هغه ورځ ښخ کړے شى، ځکه چې يو داسې مړے چې په ونه کښې ځوړند وى هغه په مُلک باندې د خُدائ پاک لعنت راولى. هغه مړے ښخ کړئ، نو تاسو به هغه مُلک پليت نۀ کړئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له په ميراث کښې درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5033, 'Deuteronomy 22:1', 'Deuteronomy', 22, 1, '&nbsp;کۀ تاسو وګورئ چې ستاسو د اِسرائيلى ورور غوا يا ګډې لار غلطه کړې وى، نو هغه هم داسې مۀ پرېږدئ، او خپل مالِک له يې واپس ورولئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5034, 'Deuteronomy 22:2', 'Deuteronomy', 22, 2, '&nbsp;خو کۀ د دې مالِک لرې اوسيږى يا کۀ تاسو ته پته نۀ وى چې دا د چا ده، نو د ځان سره يې خپل کور ته بوځئ. کله يې چې مالِک لټولو له راشى، نو هغۀ له يې ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5035, 'Deuteronomy 22:3', 'Deuteronomy', 22, 3, '&nbsp;کله چې تاسو خر، د کپړې ټُکړه، يا بل څۀ ومومئ چې ستاسو د اِسرائيلى ورور نه ورک شوې وى نو تاسو هم دغه شان کوئ. د چا سره مدد کولو نه لاس مۀ نيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5036, 'Deuteronomy 22:4', 'Deuteronomy', 22, 4, '&nbsp;کۀ ستاسو د اِسرائيلى ورور خر يا غوا په لاره کښې غورزېدلې وى، نو هغه هم داسې مۀ پرېږدئ، د هغه ځناور په پاڅولو کښې د هغۀ مدد وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5037, 'Deuteronomy 22:5', 'Deuteronomy', 22, 5, '&nbsp;ښځې دې د سړو جامې نۀ اچوى او سړى دې د ښځو جامې نۀ اغوندى، مالِک خُدائ ستاسو خُدائ پاک د هغه خلقو نه کرکه کوى څوک چې داسې کارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5038, 'Deuteronomy 22:6', 'Deuteronomy', 22, 6, '&nbsp;کۀ چرې تاسو په يوه ونه کښې يا په زمکه باندې د مارغانو جاله ووينئ چې مرغۍ په هګو باندې يا د خپلو بچو سره ناسته وى، نو تاسو به دا مرغۍ نۀ رانيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5039, 'Deuteronomy 22:7', 'Deuteronomy', 22, 7, '&nbsp;تاسو د مرغو هغه واړۀ بچى رانيولے شئ، خو مرغۍ به يې پرېږدئ چې لاړه شى، نو تاسو به يو اوږد او خوشحاله ژوند تېر کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5040, 'Deuteronomy 22:8', 'Deuteronomy', 22, 8, '&nbsp;کله چې تاسو يو نوے کور جوړ کړئ، نو ګورئ چې د چت د غاړې نه ګېرچاپېره يو پړده‌وال ورله جوړ کړئ. کۀ څوک ترې نه راوغورزيږى او مړ شى نو ذمه وارى به يې ستاسو په غاړه نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5041, 'Deuteronomy 22:9', 'Deuteronomy', 22, 9, '&nbsp;کۀ په يو پټى کښې انګور وکَرئ نو بل څۀ فصل ورسره مۀ کَرئ ګنې دواړه به نۀ شئ خوړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5042, 'Deuteronomy 22:10', 'Deuteronomy', 22, 10, '&nbsp;غوَيے او خر تاسو په يو جغ کښې د يوې کولو دپاره مۀ اچوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5043, 'Deuteronomy 22:11', 'Deuteronomy', 22, 11, '&nbsp;داسې جامې مۀ اغوندئ چې په يو ځائ د تاو شوې وړۍ او د کتان نه جوړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5044, 'Deuteronomy 22:12', 'Deuteronomy', 22, 12, '&nbsp;د خپلو جامو په څلورو ګوټونو پورې د مزو زونډى وګنډئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5045, 'Deuteronomy 22:13', 'Deuteronomy', 22, 13, '&nbsp;کۀ يو سړے يوه ښځه وادۀ کړى او ورسره څملى او وروستو يې هغه خوښه نۀ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5046, 'Deuteronomy 22:14', 'Deuteronomy', 22, 14, '&nbsp;او د هغې خِلاف داسې دروغ ووائى چې ما وادۀ کړه خو چې کله ورسره څملاستم نو ما ته پته ولګېده چې هغه زما نه مخکښې د بل سړى سره ملاسته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5047, 'Deuteronomy 22:15', 'Deuteronomy', 22, 15, '&nbsp;کۀ داسې وشى، نو د جينۍ مور او پلار دې د ښار مشرانو له د جرګې په وخت دا ثبوت راوړى چې هغه جينۍ هيڅکله هم د يو سړى سره نۀ وه ملاسته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5048, 'Deuteronomy 22:16', 'Deuteronomy', 22, 16, '&nbsp;د هغې پلار به مشرانو ته ووائى، ”ما خپله لور دې سړى له ورکړه چې وادۀ يې کړى، خو اوس د هغۀ خوښه نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5049, 'Deuteronomy 22:17', 'Deuteronomy', 22, 17, '&nbsp;هغه د دې خِلاف دا دروغ وائى چې کله ما ورسره وادۀ وکړو نو هغه د مخکښې نه د بل سړى سره ملاسته وه خو ثبوت دا دے چې زما لور صفا وه، د وادۀ د کټ په څادر باندې تاسو د وينې دا داغونه وګورئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5050, 'Deuteronomy 22:18', 'Deuteronomy', 22, 18, '&nbsp;نو د ښار مشران به د هغې خاوند بوځى او سزا به ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5051, 'Deuteronomy 22:19', 'Deuteronomy', 22, 19, '&nbsp;هغوئ دې هغه سل د سپينو زرو سيکې جرمانه هم کړى او پېسې دې د ښځې پلار له ورکړى، ځکه چې هغه سړى يوه اِسرائيلۍ ښځه رسوا کړې ده. د دې نه علاوه، هغه به يې ښځه هم وى او چې ترڅو پورې هغه ژوندے وى هغې له طلاق نۀ شى ورکولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5052, 'Deuteronomy 22:20', 'Deuteronomy', 22, 20, '&nbsp;خو کۀ دا خبره رښتيا وى او دا ثبوت نۀ وى چې هغه پېغله پاتې شوې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5053, 'Deuteronomy 22:21', 'Deuteronomy', 22, 21, '&nbsp;نو هغوئ به يې د هغې د پلار د کور دروازې خولې ته بوځى، او د ښار سړى به يې هلته سنګسار کړى چې مړه شى. هغې ستاسو خلقو په مينځ کښې يو د شرم نه ډک کار کړے دے چې د وادۀ نه مخکښې د بل سړى سره څملاستله، چې هغه لا د پلار په کور کښې وه. نو تاسو به په دې طريقې سره د خپل مينځ نه دا بدکارى ختمه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5054, 'Deuteronomy 22:22', 'Deuteronomy', 22, 22, '&nbsp;کۀ يو سړے د بل سړى د ښځې سره په زنا کولو ونيولے شى، نو هغوئ دواړه به وژلے شى، نو چې تاسو د اِسرائيل مُلک د دې بدکارۍ نه خلاص کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5055, 'Deuteronomy 22:23', 'Deuteronomy', 22, 23, '&nbsp;کۀ په يو ښار کښې يو سړے د داسې ښځې سره په زنا پورې ونيولے شى چې د هغې کوژدن د بل چا سره شوې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5056, 'Deuteronomy 22:24', 'Deuteronomy', 22, 24, '&nbsp;نو تاسو هغوئ د ښار نه بهر بوځئ او سنګسار يې کړئ چې مړۀ شى. ښځه دې ځکه مړه شى چې هغې د مدد دپاره چغې نۀ دى وهلې، اګر چې هغه په ښار کښې وه، کېدے شى چې هلته د هغې چغې اورېدلے شوې وے. او سړے دې ځکه مړ شى چې هغۀ د يوې داسې ښځې سره زنا کړې ده چې هغه کوژدن شوې وه. نو داسې به تاسو د دې ګند نه ځان خلاص کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5057, 'Deuteronomy 22:25', 'Deuteronomy', 22, 25, '&nbsp;فرض کړئ چې يو سړے په پټو کښې د يوې داسې ښځې بې‌عزتى وکړى چې د هغې کوژدن د بل چا سره شوې وى. نو صِرف هغه سړے به وژلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5058, 'Deuteronomy 22:26', 'Deuteronomy', 22, 26, '&nbsp;ښځې ته به هيڅ نۀ شى وئيلے، ځکه هغې داسې ګناه نۀ ده کړې چې د مرګ حقداره شى. دا هم هغه شان معامِله ده چې يو سړے په بل سړى باندې حمله وکړى او مړ يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5059, 'Deuteronomy 22:27', 'Deuteronomy', 22, 27, '&nbsp;هغه سړى په پټو کښې د هغه کوژدن شوې ښځې سره په زبردستۍ زنا وکړه، اګر چې هغې د مدد چغې وهلې وې، خو هيڅ څوک هم نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5060, 'Deuteronomy 22:28', 'Deuteronomy', 22, 28, '&nbsp;کۀ يو سړے د يوې داسې جينۍ سره په زبردستۍ زنا وکړى چې هغه کوژدن شوې نۀ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5061, 'Deuteronomy 22:29', 'Deuteronomy', 22, 29, '&nbsp;نو هغه به د هغې پلار له پنځوس د سپينو زرو سيکې حق مهر ورکړى او هغه به يې ښځه شى، ځکه چې هغۀ په زور باندې د هغې سره زنا کړې ده. چې تر کومې پورې ژوندے وى نو هغې له طلاق نۀ شى ورکولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5062, 'Deuteronomy 22:30', 'Deuteronomy', 22, 30, '&nbsp;يو سړے دې هم د خپل پلار بې‌عزتى نۀ کوى چې د خپل پلار د ښځو نه د يوې سره څملى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5063, 'Deuteronomy 23:1', 'Deuteronomy', 23, 1, '&nbsp;د کوم سړى چې هګۍ ماتې شوې وى يا يې ذکر پرې کړے شوے وى نو هغه يو به هم د مالِک خُدائ په خلقو کښې نۀ شى شاملېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5064, 'Deuteronomy 23:2', 'Deuteronomy', 23, 2, '&nbsp;يو حرامى پېدا شوے کس يا د داسې کس اولاد، تر لسم نسله پورې هم، د مالِک خُدائ په خلقو کښې نۀ شى شاملېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5065, 'Deuteronomy 23:3', 'Deuteronomy', 23, 3, '&nbsp;هيڅ يو عمونى يا موآبى، يا د هغوئ اولاد، تر لسم نسل پورې هم، د مالِک خُدائ په خلقو کښې نۀ شى شاملېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5066, 'Deuteronomy 23:4', 'Deuteronomy', 23, 4, '&nbsp;کله چې تاسو د مِصر نه بهر په لاره کښې وئ نو هغوئ تاسو له د خوراک او اوبو درکولو نه اِنکار وکړو او د مسوپتاميه په ښار پتور کښې يې د بعور زوئ بلعام له پېسې ورکړې چې په تاسو لعنت ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5067, 'Deuteronomy 23:5', 'Deuteronomy', 23, 5, '&nbsp;خو مالِک خُدائ ستاسو خُدائ پاک به بلعام ته غوږ نۀ نيولو، او لعنت يې په برکت بدل کړو، ځکه چې هغۀ ستاسو سره مينه لرله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5068, 'Deuteronomy 23:6', 'Deuteronomy', 23, 6, '&nbsp;چې تر کومې پورې تاسو ژوندى يئ، د هغوئ مدد مۀ کوئ چې هغوئ د خېر او خوشحالۍ ژوند وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5069, 'Deuteronomy 23:7', 'Deuteronomy', 23, 7, '&nbsp;ادوميانو ته سپک مۀ ګورئ، هغوئ ستاسو خپلوان دى. او مِصريانو ته هم سپک مۀ ګورئ، په يو وخت کښې تاسو د هغوئ په مُلک کښې اوسېدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5070, 'Deuteronomy 23:8', 'Deuteronomy', 23, 8, '&nbsp;د درېم نسل نه ورپه اخوا د هغوئ اولاد د مالِک خُدائ په خلقو کښې شاملېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5071, 'Deuteronomy 23:9', 'Deuteronomy', 23, 9, '&nbsp;کله چې تاسو د يو لښکر په شکل د خپلو دشمنانو خِلاف ووځئ، نو ګورئ د داسې هر څيز نه ځان ساتئ چې تاسو ناپاکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5072, 'Deuteronomy 23:10', 'Deuteronomy', 23, 10, '&nbsp;کۀ د شپې شېطان يو سړے دوکه کړى او هغه په دې وجه ناپاک شى، نو هغه دې د خېمو نه بهر ووځى او هلته دې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5073, 'Deuteronomy 23:11', 'Deuteronomy', 23, 11, '&nbsp;په ماښام کښې دې هغه غسل وکړى او د نمرپرېواتۀ په وخت کښې هغه واپس کېمپ ته راتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5074, 'Deuteronomy 23:12', 'Deuteronomy', 23, 12, '&nbsp;تاسو له په کار دى چې د کېمپ نه بهر يو ځائ جوړ کړئ چې هلته د اودس ماتى دپاره ځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5075, 'Deuteronomy 23:13', 'Deuteronomy', 23, 13, '&nbsp;په خپل سامان کښې د کنستلو دپاره يو څيز هم يوسئ، کله چې تاسو ډکې متيازې کوئ نو يوه کنده به وکنئ او متيازې به په کښې پټې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5076, 'Deuteronomy 23:14', 'Deuteronomy', 23, 14, '&nbsp;خپل کېمپ مقدس ساتئ، ځکه چې مالِک خُدائ ستاسو خُدائ پاک تاسو سره ستاسو په کېمپ کښې دے، دا د دې دپاره چې ستاسو حِفاظت وکړى او تاسو له په دشمنانو باندې فتح درکړى. داسې يو د بې‌شرمۍ کار هم مۀ کوئ چې د هغې په وجه مالِک خُدائ ستاسو نه مخ واړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5077, 'Deuteronomy 23:15', 'Deuteronomy', 23, 15, '&nbsp;کۀ غلامان د خپلو مالِکانو نه وتښتى او تاسو له د پناه دپاره راشى، نو هغوئ واپس مۀ لېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5078, 'Deuteronomy 23:16', 'Deuteronomy', 23, 16, '&nbsp;هغوئ ستاسو د ښارونو په هر يو ښار کښې اوسېدے شى چې کوم يې خوښ وى او تاسو به د هغوئ سره زياتے نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5079, 'Deuteronomy 23:17', 'Deuteronomy', 23, 17, '&nbsp;اِسرائيلے سړے يا ښځه به هيڅکله د عبادتخانې کنجران نۀ جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5080, 'Deuteronomy 23:18', 'Deuteronomy', 23, 18, '&nbsp;د کنجر سړى يا د کنجرې ښځې ګټلے شوې پېسې به هم د يوې منښتې پوره کولو دپاره د مالِک خُدائ ستاسو خُدائ پاک کور ته نۀ شى راوړلے. مالِک خُدائ د عبادتخانې د کنجرانو نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5081, 'Deuteronomy 23:19', 'Deuteronomy', 23, 19, '&nbsp;کله چې تاسو پېسې يا خوراک، يا بل څيز خپل اِسرائيلى ورور له قرض ورکړئ، نو د هغۀ نه سود مۀ اخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5082, 'Deuteronomy 23:20', 'Deuteronomy', 23, 20, '&nbsp;يو مسافر له چې څۀ څيز قرض ورکړئ نو د هغې سود د هغۀ نه اخستے شئ، خو چې خپل اِسرائيلى له څۀ قرض ورکړئ نو د هغې سود به ترې نه نۀ اخلئ. دا اصُول ومنئ او مالِک خُدائ ستاسو خُدائ پاک به په هغه مُلک کښې تاسو له په هر کار کښې برکت درکړى کوم مُلک چې تاسو قبضه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5083, 'Deuteronomy 23:21', 'Deuteronomy', 23, 21, '&nbsp;کله چې مالِک خُدائ خپل خُدائ پاک ته تاسو يوه منښته ومنئ، نو چې کومه وعده مو کړې وى په هغې کښې سستى مۀ کوئ، مالِک خُدائ به ستاسو نه د هغه منښتې تپوس کوى او د دې وعدې نۀ پوره کول ګناه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5084, 'Deuteronomy 23:22', 'Deuteronomy', 23, 22, '&nbsp;مالِک خُدائ ته منښته نۀ منل ګناه نۀ ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5085, 'Deuteronomy 23:23', 'Deuteronomy', 23, 23, '&nbsp;خو کۀ تاسو په خپله خوښه يوه منښته ومنئ، نو ګورئ هغه وعده به پوره کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5086, 'Deuteronomy 23:24', 'Deuteronomy', 23, 24, '&nbsp;کله چې تاسو د بل چا د انګورو باغ سره تېرېږئ، نو چې څومره انګور غواړئ هغه خوړلے شئ، خو د هغې نه به په يوه ټوکرۍ کښې انګور نۀ وړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5087, 'Deuteronomy 23:25', 'Deuteronomy', 23, 25, '&nbsp;هم دغه شان، کۀ تاسو د بل چا د فصل په پټى کښې ګرځئ، څومره غله چې د خپلو لاسونو سره راشوکولے شئ هغه خوړے شئ، خو هغه فصل به تاسو په لور نۀ رېبئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5088, 'Deuteronomy 24:1', 'Deuteronomy', 24, 1, '&nbsp;کۀ يو سړے يوې ښځې سره وادۀ وکړى او په هغې کښې داسې څۀ وګورى چې د هغه سړى خوښ نۀ وى او وروستو فېصله وکړى چې خپله ښځه طلاقه کړى او هغه طلاق نامه ورکړى او د خپل کور نه يې وشړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5089, 'Deuteronomy 24:2', 'Deuteronomy', 24, 2, '&nbsp;او بيا کۀ هغه ښځه د هغه سړى د کور نه لاړه شى او د بل سړى سره وادۀ وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5090, 'Deuteronomy 24:3', 'Deuteronomy', 24, 3, '&nbsp;او کۀ د هغه دوېم خاوند هم خوښه نۀ شى او هغه هم طلاق نامه ورکړى او د خپل کور نه يې وشړى، يا فرض کړئ چې دا خاوند يې مړ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5091, 'Deuteronomy 24:4', 'Deuteronomy', 24, 4, '&nbsp;نو په دواړو حالاتونو کښې به د هغې وړومبے خاوند هغه ښځه دوباره نۀ وادۀ کوى، هغه به يې ناپاکه ګڼى. کۀ دوباره وادۀ يې ورسره وکړو نو مالِک خُدائ به د دې کار نه نفرت کوى. تاسو به هغه مُلک په داسې خرابه ګناه نۀ پليتوئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى چې ستاسو خپل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5092, 'Deuteronomy 24:5', 'Deuteronomy', 24, 5, '&nbsp;کله چې يو سړے نوے وادۀ وکړى، نو هغه دې د جنګ دپاره فوج ته نۀ شى لېږلے او نۀ دې ترې نه کار اخستلے شى، يو کال به هغۀ ته کار معاف وى، نو چې داسې هغه په کور کښې پاتې شى او ښځه خوشحاله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5093, 'Deuteronomy 24:6', 'Deuteronomy', 24, 6, '&nbsp;کله چې تاسو چا له څۀ څيز قرض ورکړئ، نو چې د هغۀ نه په ضمانت کښې د هغۀ د مېچنې برنے پل وانۀ خلئ چې په هغې باندې غله مېده کوى. کۀ تاسو ترې نه دا واخلئ نو د دانو اوړۀ کولو ذريعه به يې ختمه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5094, 'Deuteronomy 24:7', 'Deuteronomy', 24, 7, '&nbsp;کۀ يو سړے د خپل اِسرائيلى په تښتولو پورې ونيولے شى او خپل غلام يې کړى يا د غلام په توګه يې خرڅ کړى نو هغه سړے دې ووژلے شى. نو داسې به تاسو د دې بدکارۍ نه خپل قوم خلاص کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5095, 'Deuteronomy 24:8', 'Deuteronomy', 24, 8, '&nbsp;کله چې تاسو د جذام بيمارۍ په وجه په تکليف کښې يئ، نو هم هغه شان کوئ څنګه چې درته د ليوى قبيلې اِمامان وائى، ما چې هغوئ ته کوم اصُول ښودلى دى په هغې عمل کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5096, 'Deuteronomy 24:9', 'Deuteronomy', 24, 9, '&nbsp;ياد ساتئ کله چې تاسو د مِصر نه راروان وئ نو مالِک خُدائ ستاسو خُدائ پاک د مريم سره څۀ وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5097, 'Deuteronomy 24:10', 'Deuteronomy', 24, 10, '&nbsp;کله چې تاسو خپل ګاونډى له څۀ قرض ورکوئ، نو د هغۀ کور ته د دې دپاره مۀ ځئ چې هغه څيز ترې نه واخلئ چې په ضمانت کښې يې تاسو له درکوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5098, 'Deuteronomy 24:11', 'Deuteronomy', 24, 11, '&nbsp;بهر ورته ودرېږئ او پرېږدئ چې هغه څيز په خپله تاسو له راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5099, 'Deuteronomy 24:12', 'Deuteronomy', 24, 12, '&nbsp;کۀ هغه غريب وى او د قرض په ضمانت کښې هغه تاسو له خپله چُوغه درکړى، نو هغه چُوغه د شپې د ځان سره مۀ ساتئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5100, 'Deuteronomy 24:13', 'Deuteronomy', 24, 13, '&nbsp;دا چُوغه په ماښام کښې هغۀ له واپس ورکوئ، نو چې داسې هغه په کښې اودۀ کيږى. نو هغه به ستاسو شکريه ادا کړى او د مالِک خُدائ ستاسو خُدائ پاک په نظر کښې به ستاسو دپاره د دې اجر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');